// DefaultAccount คือบัญชีหนึ่งรายการของผังบัญชีมาตรฐาน (สร้างให้บริษัทที่ยังไม่มีบัญชีด้วย POST /accounts/defaults)
type DefaultAccount struct {
	Code        string
	ParentCode  string // ว่าง = บัญชีระดับบนสุด (หมวด)
	Type        vo.AccountType
	Postable    bool // false = บัญชีคุม (กลุ่มบัญชี) ใช้รวมยอด
	Name        string
	NameEN      string
	Description string
}

